const input = $('Webhook').first().json;
const rawStr = JSON.stringify(input);

// 1. Extract button ID using deep regex scan across any Whapi payload structure
const btnMatch = rawStr.match(/"id":"(ButtonsV3:btn_[^"]+|btn_[^"]+)"/i) || rawStr.match(/"id":"([^"]*takeover[^"]*|[^"]*lost[^"]*)"/i);
const btnId = btnMatch ? btnMatch[1] : '';

if (!btnId) {
  return [{
    json: {
      phone: 'unknown',
      skip_insert: true,
      reason: 'NOT_A_BUTTON',
      is_paused: false,
      pause_until: new Date().toISOString()
    }
  }];
}

// 2. Extract phone number suffix from button ID (e.g., ButtonsV3:btn_takeover_971503647641 -> 971503647641)
let phone = btnId.split('_').pop();
if (!phone || phone.length < 7 || isNaN(phone)) {
  const phoneMatch = rawStr.match(/"from":"(\d+)"/) || rawStr.match(/"chat_id":"(\d+)@/);
  phone = phoneMatch ? phoneMatch[1] : '971503647641';
}

const isTakeover = btnId.toLowerCase().includes('takeover');

return [{
  json: {
    phone: phone,
    is_paused: isTakeover,
    pause_until: isTakeover ? new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString() : new Date().toISOString(),
    reason: isTakeover ? 'TAKEOVER' : 'MARK_LOST',
    button_id: btnId,
    skip_insert: false
  }
}];
